def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if not isinstance(value, timedelta):
        raise TypeError("Expected a timedelta instance")
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    try:
        if not isinstance(value, time):
            raise ValueError("Input value must be of type time.")
        return value.strftime("%H:%M:%S")
    except Exception as e:
        raise RuntimeError(f"Error dehydrating time: {e}")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Expected a Point instance, got {}".format(type(value).__name__))

    try:
        return {
            'x': value.x,
            'y': value.y
        }
