def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            if metadata is not None and not isinstance(metadata, dict):
                raise ValueError("Metadata must be a dictionary.")
            if timeout is not None and (not isinstance(timeout, (int, float)) or timeout < 0):
                raise ValueError("Timeout must be a non-negative number or None.")
            return func(tx, *args, **kwargs)
        wrapper._metadata = metadata
        wrapper._timeout = timeout
        return wrapper
    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f"Key {key} not found in the list.")
    except AttributeError:
        raise TypeError("The method 'index' is not applicable to the current object type.")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    try:
        if not keys:
            return list(self._data.values())
        else:
            return [self._data[key] for key in keys]
    except KeyError as e:
        raise ValueError(f"Key {e} not found in the record.") from e
    except TypeError as e:
        raise ValueError(f"Invalid key type: {e}") from e

def data(self, *keys):
    result = {}
    if not keys:
        return dict(self._data)
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._data):
                raise IndexError(f"Index {key} is out of bounds")
            result[list(self._data.keys())[key]] = list(self._data.values())[key]
        else:
            result[key] = self._data.get(key, None)
    return result

