def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not isinstance(bins, (list, tuple)) or not isinstance(edges, (list, tuple)):
        raise ValueError("Both bins and edges must be lists or tuples.")
    if len(bins) != len(edges) - 1:
        raise ValueError("The number of bins must be one less than the number of edges.")

    total = 0.0
    for i in range(len(bins)):
        if not isinstance(bins[i], (int, float)):
            raise ValueError("All elements in bins must be numbers.")
        if not isinstance(edges[i], (int, float)) or not isinstance(edges[i + 1], (int, float)):
            raise ValueError("All elements in edges must be numbers.")
        width = edges[i + 1] - edges[i]
        if width < 0:
            raise ValueError("Edges must be in non-decreasing order.")
        total += bins[i] * width

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if not isinstance(seq, (list, tuple)):
        raise ValueError("seq must be a list or tuple")

    def is_fill_request(element):
        # Assuming FillRequest is a specific type or class, replace 'FillRequest' with the actual type
        return isinstance(element, FillRequest)

    def is_source_sequence(element):
        # Assuming Source is a specific type or class, replace 'Source' with the actual type
        return isinstance(element, Source)

    if is_source_sequence(seq):
        return False

    if is_fill_request(seq):
        return True

    for element in seq:
        if is_fill_request(element):
            return True

    return False

