    spec_version = self.spec_version

    if extract_spec_version:
        type_value = inventory.get('type')
        if type_value == 'spec_version_1':
            spec_version = '1.0'
        elif type_value == 'spec_version_2':
            spec_version = '2.0'
        # Add more type to version mappings as needed
        # If type_value is not recognized or missing, use self.spec_version

    # Perform validation based on the determined spec_version
    if spec_version == '1.0':
        # Validation logic for version 1.0
        if 'required_field_1' not in inventory:
            raise ValueError("Missing required field 'required_field_1' for spec version 1.0")
    elif spec_version == '2.0':
        # Validation logic for version 2.0
        if 'required_field_2' not in inventory:
