def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise ValueError("manifest_files must be a dictionary.")
    if not isinstance(digests_used, set):
        raise ValueError("digests_used must be a set.")

    all_digests = set()
    for file_data in manifest_files.values():
        if not isinstance(file_data, dict) or 'digest' not in file_data:
            raise ValueError("Each entry in manifest_files must be a dictionary containing a 'digest' key.")
        all_digests.add(file_data['digest'])

    missing_digests = all_digests - digests_used
    if missing_digests:
        raise Exception(f"Digests present in manifest but not used: {missing_digests}")

    return True

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The prior argument must be an instance of InventoryValidator.")

    # Assuming there are attributes like version or timestamp to compare
    if prior.version >= self.version:
        raise ValueError("The prior version must be older than the current version.")

    # Additional checks can be added here if necessary
    # For example, checking if all items in prior are present in self with at least the same quantity
    for item, quantity in prior.items.items():
        if item not in self.items or self.items[item] < quantity:
            raise ValueError(f"Item {item} in prior version is not present or has a higher quantity in the current version.")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")
    if not isinstance(version, str):
        raise ValueError("Version must be a string.")

    if version not in inventory:
        raise KeyError(f"Version {version} not found in inventory.")

    logical_path_map = {}

    for logical_path, details in inventory.get(version, {}).items():
        if not isinstance(details, dict) or 'files' not in details:
            raise ValueError(f"Invalid entry for {logical_path} in version {version}.")

        files = details.get('files', [])
        if not isinstance(files, list):
            raise ValueError(f"Files for {logical_path} in version {version} must be a list.")

        logical_path_map[logical_path] = set(files)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list.")

    for file_name in fixity:
        if file_name not in manifest_files:
            raise ValueError(f"File '{file_name}' in fixity block is not listed in the manifest.")

    return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"The path {path} does not exist.")
        if not os.path.isdir(path):
            raise NotADirectoryError(f"The path {path} is not a directory.")
        return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]
    except Exception as e:
        return str(e)

