def fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime object")
    if dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")

    # Calculate the equivalent time in the new timezone
    new_dt = self.normalize(self.localize(dt.replace(tzinfo=None)))

    # Check if the datetime is in a fold state
    if new_dt.fold:
        # It's the first occurrence of the ambiguous datetime
        return new_dt
    else:
        # It's the second occurrence of the ambiguous datetime
        return self.normalize(new_dt.replace(fold=1))

def default_tzinfo(dt, tzinfo):
