def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise ValueError("command_name must be a string")

    try:
        # Assuming self.parser_options is a dictionary holding command options
        return self.parser_options[command_name]
    except KeyError:
        raise KeyError(f"No options found for command: {command_name}")
    except AttributeError:
        raise AttributeError("self.parser_options is not defined")

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        if not isinstance(command_name, str) or not isinstance(argument_name, str):
            raise ValueError("Both command_name and argument_name must be strings.")

        if not hasattr(self, 'command_specs') or command_name not in self.command_specs:
            raise KeyError(f"Command '{command_name}' not found in specifications.")

        command_spec = self.command_specs[command_name]
        if argument_name not in command_spec:
            raise KeyError(f"Argument '{argument_name}' not found in command '{command_name}' specifications.")

        return command_spec[argument_name]

    except Exception as e:
        raise Exception(f"Error retrieving option specification: {e}")

def get_silent_args(self, args):
