    """
    try:
        if not isinstance(args, dict):
            raise ValueError("Arguments must be provided as a dictionary.")

        silenced_args = [key for key, value in args.items() if value is None]
        return silenced_args
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing arguments: {e}")

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    required_args = getattr(self, 'required_args', [])
    if not isinstance(required_args, list):
        raise AttributeError("The 'required_args' attribute must be a list.")

    missing_args = [arg for arg in required_args if arg not in args]
    if missing_args:
        raise ValueError(f"Missing required arguments: {', '.join(missing_args)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    if not isinstance(command_name, str):
        raise ValueError("command_name must be a string")
    if not isinstance(options_spec, list):
        raise ValueError("options_spec must be a list")
    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary")

    required_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if isinstance(condition, str):
                condition = {condition: True}
            elif not isinstance(condition, dict):
                raise ValueError("required_when must be a string or dictionary")

            condition_met = True
            for key, value in condition.items():
                if args.get(key) != value:
                    condition_met = False
                    break

            if condition_met:
                required_args.append(option['name'])

    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary with 'value' and 'max_length' keys.")

    for key, value in args.items():
        if not isinstance(value, dict) or 'value' not in value or 'max_length' not in value:
            raise ValueError(f"Each argument must be a dictionary with 'value' and 'max_length' keys. Invalid entry for key: {key}")

        val = value['value']
        max_len = value['max_length']

        if not isinstance(val, str):
            raise ValueError(f"The value for key '{key}' must be a string.")

        if not isinstance(max_len, int) or max_len < 0:
            raise ValueError(f"The max_length for key '{key}' must be a non-negative integer.")

        if len(val) > max_len:
            raise ValueError(f"The value for key '{key}' is longer than the specified max_length of {max_len}.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for arg_name, arg_value in args.items():
        choices = getattr(self, f"{arg_name}_choices", None)
        if choices is not None and arg_value not in choices:
            raise ValueError(f"Invalid value for {arg_name}: {arg_value}. Must be one of {choices}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary with 'value', 'min', and 'max' keys.")

    for arg_name, arg_info in args.items():
        if not isinstance(arg_info, dict) or 'value' not in arg_info or 'min' not in arg_info or 'max' not in arg_info:
            raise ValueError(f"Each argument must be a dictionary with 'value', 'min', and 'max' keys. Error in argument: {arg_name}")

        value = arg_info['value']
        min_value = arg_info['min']
        max_value = arg_info['max']

        if not isinstance(value, (int, float)) or not isinstance(min_value, (int, float)) or not isinstance(max_value, (int, float)):
            raise ValueError(f"Values for 'value', 'min', and 'max' must be numbers. Error in argument: {arg_name}")

        if value < min_value or value > max_value:
            raise ValueError(f"Value for {arg_name} is out of the allowed range. Expected between {min_value} and {max_value}, got {value}.")

